std::vector<double> Matrix::SumPerColumn() const {
    std::vector<std::size_t> cols(cols_);
    std::iota(cols.begin(), cols.end(), std::size_t{0});
    std::vector<double> result(cols_);
    const double* base = data_.data();
    std::transform(cols.begin(), cols.end(), result.begin(),
                   [base, this](std::size_t c) {
                       std::vector<const double*> ptrs;
                       ptrs.reserve(rows_);
                       for (std::size_t r = 0; r < rows_; ++r) {
                           ptrs.push_back(base + r * cols_ + c);
                       }
                       return std::accumulate(
                           ptrs.begin(), ptrs.end(), 0.0,
                           [](double acc, const double* p) { return acc + *p; });
                   });
    return result;
}

